int __cdecl main_0(int argc, const char **argv, const char **envp)&#123;  size_t v3; // eax  const char *v4; // eax  size_t v5; // eax  char v7; // [esp+0h] [ebp-188h]  char v8; // [esp+0h] [ebp-188h]  signed int j; // [esp+DCh] [ebp-ACh]  int i; // [esp+E8h] [ebp-A0h]  signed int v11; // [esp+E8h] [ebp-A0h]  char Destination[108]; // [esp+F4h] [ebp-94h] BYREF  char Str[28]; // [esp+160h] [ebp-28h] BYREF  _BYTE v14[8]; // [esp+17Ch] [ebp-Ch] BYREF  for ( i = 0; i &lt; 100; ++i )  &#123;    if ( (unsigned int)i &gt;= 0x64 )      j____report_rangecheckfailure();    Destination[i] = 0;  &#125;  sub_41132F(&quot;please enter the flag:&quot;, v7);     // 提示输入flag  sub_411375(&quot;%20s&quot;, (char)Str);                // 输入20长度，保存到Str  v3 = j_strlen(Str);                           // Str的长度  v4 = (const char *)sub_4110BE(Str, v3, v14);  // Base64编码用户输入的内容，返回值 v4 很可能是加密后的字符串  strncpy(Destination, v4, 0x28u);              // 将加密后的字符串拷贝到 Destination 中，最多拷贝 0x28 (40) 字节  v11 = j_strlen(Destination);                  // 获取 Destination 当前内容的长度（即加密后字符串的长度）  for ( j = 0; j &lt; v11; ++j )                   // 对 Destination 中的每个字符进行“简单加密”：每个字符加上其索引,例如：Destination[0] += 0; Destination[1] += 1; ...    Destination[j] += j;  v5 = j_strlen(Destination);                   // 再次获取 Destination 加密后的长度  if ( !strncmp(Destination, Str2, v5) )        // 将处理后的 Destination 与一个名为 Str2 的全局字符串进行比较    sub_41132F(&quot;rigth flag!\n&quot;, v8);  else    sub_41132F(&quot;wrong flag!\n&quot;, v8);  return 0;&#125;
